-- Bois Loisirs : gestion des réalisations (galerie « évolution du chantier »).
-- À exécuter une fois dans Supabase > SQL Editor (après supabase/schema.sql). Le script peut être relancé sans risque.
-- Le bucket Storage « site-media » (public) est celui déjà utilisé pour les photos produits.

create table if not exists public.chantiers (
  id bigint generated by default as identity primary key,
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title text not null check (char_length(title) between 3 and 120),
  category text not null default 'Autre',
  summary text not null default '' check (char_length(summary) <= 400),
  published boolean not null default true,
  featured boolean not null default false,
  position integer not null default 0,
  created_at timestamptz not null default now()
);

create table if not exists public.chantier_photos (
  id bigint generated by default as identity primary key,
  chantier_id bigint not null references public.chantiers(id) on delete cascade,
  url text not null check (url ~ '^(https://|/)'),
  alt text not null default '' check (char_length(alt) <= 200),
  phase text check (phase in ('avant','pendant','apres')),
  position integer not null default 0,
  created_at timestamptz not null default now()
);

create index if not exists chantier_photos_chantier_idx on public.chantier_photos (chantier_id, position);

alter table public.chantiers enable row level security;
alter table public.chantier_photos enable row level security;

drop policy if exists "public can read published chantiers" on public.chantiers;
create policy "public can read published chantiers" on public.chantiers for select
  using (published or public.is_admin());

drop policy if exists "admins can write chantiers" on public.chantiers;
create policy "admins can write chantiers" on public.chantiers for all
  using (public.is_admin()) with check (public.is_admin());

drop policy if exists "public can read photos of published chantiers" on public.chantier_photos;
create policy "public can read photos of published chantiers" on public.chantier_photos for select
  using (public.is_admin() or exists (select 1 from public.chantiers c where c.id = chantier_id and c.published));

drop policy if exists "admins can write chantier photos" on public.chantier_photos;
create policy "admins can write chantier photos" on public.chantier_photos for all
  using (public.is_admin()) with check (public.is_admin());

-- Storage : le client doit pouvoir supprimer ses propres fichiers
drop policy if exists "admins can delete site media" on storage.objects;
create policy "admins can delete site media" on storage.objects for delete
  using (bucket_id = 'site-media' and public.is_admin());

-- Données de départ (les réalisations déjà présentes sur le site)
do $$
declare
  seed jsonb;
  photo jsonb;
  cid bigint;
begin
  for seed in select * from jsonb_array_elements($seed$[{"slug":"abattage-helecine","title":"Abattage à Hélécine","category":"Abattage","summary":"Abattage d'un grand arbre en site arboré, avec câble de traction puis débitage du tronc.","featured":true,"position":10,"photos":[{"url":"/realisations/abattage-helecine/01.webp","alt":"Arbres sur pied avant l'abattage","phase":"avant","position":1},{"url":"/realisations/abattage-helecine/02.webp","alt":"Câble de traction fixé au tronc","phase":"pendant","position":2},{"url":"/realisations/abattage-helecine/03.webp","alt":"Tronc abattu et tronçonneuse","phase":"pendant","position":3},{"url":"/realisations/abattage-helecine/04.webp","alt":"Rondins débités sur la pelouse","phase":"apres","position":4}]},{"slug":"abattage-hetre","title":"Abattage d'un hêtre au bord d'un étang","category":"Abattage","summary":"Évacuation et débitage d'un hêtre tombé au bord de l'eau.","featured":false,"position":20,"photos":[{"url":"/realisations/abattage-hetre/01.webp","alt":"Hêtre tombé au bord de l'étang","phase":"avant","position":1},{"url":"/realisations/abattage-hetre/02.webp","alt":"Hêtre couché sur la rive","phase":"pendant","position":2},{"url":"/realisations/abattage-hetre/03.webp","alt":"Tronc débité en tronçons","phase":"pendant","position":3},{"url":"/realisations/abattage-hetre/04.webp","alt":"Souche et branches sur la berge","phase":"apres","position":4}]},{"slug":"abattage-tempete","title":"Intervention après tempête","category":"Abattage","summary":"Dégagement d'un arbre tombé près d'une habitation, avec le chargeur télescopique.","featured":false,"position":30,"photos":[{"url":"/realisations/abattage-tempete/01.webp","alt":"Arbre tombé contre la maison","phase":"avant","position":1},{"url":"/realisations/abattage-tempete/02.webp","alt":"Arbre en cours de découpe","phase":"pendant","position":2},{"url":"/realisations/abattage-tempete/03.webp","alt":"Tronc tombé sur la pelouse","phase":"pendant","position":3},{"url":"/realisations/abattage-tempete/04.webp","alt":"Chargeur télescopique dégageant le tronc","phase":"apres","position":4}]},{"slug":"nivellement-terrain","title":"Nettoyage et nivellement de terrain","category":"Nivellement","summary":"Terrain en friche dessouché, nettoyé puis nivelé.","featured":true,"position":40,"photos":[{"url":"/realisations/nivellement-terrain/01.webp","alt":"Terrain en friche avant travaux","phase":"avant","position":1},{"url":"/realisations/nivellement-terrain/02.webp","alt":"Dessouchage avec le chargeur","phase":"pendant","position":2},{"url":"/realisations/nivellement-terrain/03.webp","alt":"Terrain dégagé","phase":"pendant","position":3},{"url":"/realisations/nivellement-terrain/04.webp","alt":"Terrain nivelé","phase":"apres","position":4}]},{"slug":"terrassement-piscine","title":"Terrassement pour piscine, citerne…","category":"Terrassement","summary":"Travaux de terrassement réalisés par Bois Loisirs.","featured":true,"position":50,"photos":[{"url":"/realisations/terrassement-piscine/01.webp","alt":"Travaux de terrassement","phase":null,"position":1}]},{"slug":"amenagement-terrasse","title":"Aménagements extérieurs","category":"Aménagement extérieur","summary":"Carport, dalle de béton, terrasse, palissades.","featured":true,"position":60,"photos":[{"url":"/realisations/amenagement-terrasse/01.webp","alt":"Aménagement extérieur","phase":null,"position":1}]}]$seed$::jsonb) loop
    insert into public.chantiers (slug, title, category, summary, featured, position)
    values (seed->>'slug', seed->>'title', seed->>'category', seed->>'summary', (seed->>'featured')::boolean, (seed->>'position')::int)
    on conflict (slug) do nothing
    returning id into cid;
    if cid is not null then
      for photo in select * from jsonb_array_elements(seed->'photos') loop
        insert into public.chantier_photos (chantier_id, url, alt, phase, position)
        values (cid, photo->>'url', photo->>'alt', photo->>'phase', (photo->>'position')::int);
      end loop;
    end if;
    cid := null;
  end loop;
end $$;
